steps.command:
$Source = "C:\Test\1GB-Test.bin"
$Destination = "\\WS-CBR\TestShare\1GB-Test.bin"
if (-not (Test-Path $Source)) { fsutil file createnew $Source 1073741824 | Out-Null }
$Size = (Get-Item $Source).Length
$Time = Measure-Command { Copy-Item $Source $Destination -Force }
[pscustomobject]@{
  Direction = "SYD-to-CBR"
  Seconds = $Time.TotalSeconds
  Kbps = [math]::Round(($Size * 8) / $Time.TotalSeconds / 1000, 2)
} | ConvertTo-Json -Compress

